CREATE TABLE IF NOT EXISTS site_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id),message TEXT NOT NULL DEFAULT '',verse_ref TEXT NOT NULL DEFAULT '',verse_text TEXT NOT NULL DEFAULT '',likes TEXT NOT NULL DEFAULT '',gifts TEXT NOT NULL DEFAULT '',dislikes TEXT NOT NULL DEFAULT '',avatar TEXT NOT NULL DEFAULT 'luz',photo TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'Pendiente',updated TEXT NOT NULL,reviewed_by INTEGER REFERENCES users(id),reviewed TEXT NOT NULL DEFAULT '',demo INTEGER NOT NULL DEFAULT 0);
